{"command":"$utf8NoBom = [System.Text.UTF8Encoding]::new($false)
$files = @(
    @{ Path = 'Script\Blueprint\UGCPlayerController.lua'; Name = 'UGCPlayerController'; Header = '---@class UGCPlayerController_C:BP_UGCPlayerController_C' },
    @{ Path = 'Script\Blueprint\UGCPlayerPawn.lua'; Name = 'UGCPlayerPawn'; Header = '---@class UGCPlayerPawn_C:BP_UGCPlayerPawn_C' },
    @{ Path = 'Script\Blueprint\UGCPlayerState.lua'; Name = 'UGCPlayerState'; Header = $null },
    @{ Path = 'Script\Blueprint\UGCGameMode.lua'; Name = 'UGCGameMode'; Header = '---@class UGCGameMode_C:BP_UGCGameBase_C' }
)
foreach ($file in $files) {
    $path = Join-Path (Get-Location) $file.Path
    $original = [System.IO.File]::ReadAllText($path, $utf8NoBom)
    if ($original -match 'Original implementation disabled for clean-start script') {
        continue
    }
    $lines = $original -split "`r?`n", -1
    $commented = $lines | ForEach-Object { '-- ' + $_ }
    $newLines = New-Object System.Collections.Generic.List[string]
    if ($file.Header) { $newLines.Add($file.Header) }
    $newLines.Add('-- Original implementation disabled for clean-start script.')
    $newLines.Add('-- The previous code is preserved below as line comments for restoration if needed.')
    $newLines.Add('local ' + $file.Name + ' = {}')
    $newLines.Add('')
    $newLines.Add('-- Disabled original implementation:')
    foreach ($line in $commented) { $newLines.Add($line) }
    $newLines.Add('')
    $newLines.Add('return ' + $file.Name)
    [System.IO.File]::WriteAllText($path, ($newLines -join "`r`n"), $utf8NoBom)
}
